package com.personal.assistant.module.scheduler.job;import com.personal.assistant.module.scheduler.service.SchedulerJobService;import org.quartz.*;public class DispatchQuartzJob implements Job {private final SchedulerJobService service;public DispatchQuartzJob(SchedulerJobService s){service=s;}@Override public void execute(JobExecutionContext context)throws JobExecutionException{Long id=context.getMergedJobDataMap().getLong("jobId");service.execute(id);}}